/**
 * `ProjectOp`: the scripted edits `window.clipStacker.project.apply` takes.
 *
 * One declarative spec per op drives the TypeScript-facing docs, the JSON
 * Schema (`docs/project-ops.schema.json`, regenerated by
 * `UPDATE_PROJECT_OPS_SCHEMA=1 npx vitest --run src/actions/projectOps`) and
 * the validator, so they cannot disagree. Every op maps onto an existing
 * editor action or pure edit (`timeline/editModes.ts`, `trackModel.ts`, the
 * finishing preset path); `apply.ts` is that mapping. Times are seconds:
 * `startTime` / `time` on the output timeline, `trimStart` / `trimEnd` in the
 * clip's source.
 */

export type FieldSchema =
  | { type: 'string'; enum?: readonly string[]; minLength?: number }
  | { type: 'number'; minimum?: number; maximum?: number }
  | { type: 'integer'; minimum?: number }
  | { type: 'boolean' }
  | { type: 'array'; items: FieldSchema; maxItems?: number }
  /** `fields`: a closed object; without it any object (checked by the op itself). */
  | { type: 'object'; fields?: Readonly<Record<string, FieldSpec>> };

export interface FieldSpec {
  schema: FieldSchema;
  required?: boolean;
  description: string;
}

export interface OpSpec {
  description: string;
  fields: Readonly<Record<string, FieldSpec>>;
}

const str = (description: string, required = false): FieldSpec => ({ schema: { type: 'string', minLength: 1 }, description, required });
const num = (description: string, required = false, minimum?: number): FieldSpec => ({
  schema: minimum === undefined ? { type: 'number' } : { type: 'number', minimum },
  description,
  required,
});
const bool = (description: string): FieldSpec => ({ schema: { type: 'boolean' }, description });
const obj = (description: string, required = false): FieldSpec => ({ schema: { type: 'object' }, description, required });
const choice = (values: readonly string[], description: string, required = false): FieldSpec => ({
  schema: { type: 'string', enum: values },
  description,
  required,
});

const KEYFRAME: FieldSchema = {
  type: 'object',
  fields: {
    t: { schema: { type: 'number', minimum: 0 }, required: true, description: 'Clip-local time, seconds.' },
    value: { schema: { type: 'number' }, required: true, description: 'Value at `t`.' },
  },
};

export const DROP_MODES = ['overwrite', 'insert'] as const;
export const KEYFRAME_PROPS = [
  'x', 'y', 'width', 'height', 'opacity', 'uvScaleX', 'uvScaleY', 'uvOffsetX', 'uvOffsetY',
  'rotation', 'scaleX', 'scaleY', 'anchorX', 'anchorY', 'volume', 'pan', 'playbackRate',
] as const;
export const TRACK_KINDS = ['video', 'audio', 'text'] as const;
export const TIMECODE_RATE_IDS = ['23.976', '24', '25', '29.97', '29.97df', '30', '50', '59.94', '59.94df', '60'] as const;

/** Clip fields `setClip` may change (the rest have their own op). */
export const SET_CLIP_FIELDS: Readonly<Record<string, FieldSpec>> = {
  title: str('Clip name.'),
  volume: num('Linear gain, 0–2.', false, 0),
  opacity: num('0–1.', false, 0),
  x: num('Overlay left edge, fraction of the output width.'),
  y: num('Overlay top edge, fraction of the output height.'),
  width: num('Overlay width, fraction of the output (0 = source width).', false, 0),
  height: num('Overlay height, fraction of the output (0 = source height).', false, 0),
  playbackRate: num('Constant speed, 0.25–4.', false, 0.25),
  loopCount: { schema: { type: 'integer', minimum: 1 }, description: 'Play the trimmed window this many times.' },
  reversed: bool('Play the trimmed window backward.'),
  videoFadeIn: num('Seconds.', false, 0),
  videoFadeOut: num('Seconds.', false, 0),
  audioFadeIn: num('Seconds.', false, 0),
  audioFadeOut: num('Seconds.', false, 0),
  stabilize: bool('Stabilize the clip (analysis runs in the background).'),
  overlayBlend: choice(['opaque', 'source-alpha', 'premultiplied', 'chroma', 'luma'], 'How an overlay keys against the layers below.'),
  chromaKey: obj('`{ color, similarity, blend }` for chroma / luma keys.'),
};

